-- Gem balance: smaller daily claim, daily card needs a papyrus sent or replied today, smaller card/riddle/streak rewards.
update public.journey_stations set gems = 3;
CREATE OR REPLACE FUNCTION public.card_reveal(p_pick integer) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare w public.wallet; today date := (now() at time zone 'utc')::date; used int; r int; reward int; begin if auth.uid() is null then raise exception 'auth'; end if; if p_pick is null or p_pick < 0 or p_pick > 8 then raise exception 'bad_pick'; end if; insert into public.wallet(uid) values (auth.uid()) on conflict do nothing; select * into w from public.wallet where uid = auth.uid() for update; used := case when w.cards_day = today then w.cards_used else 0 end; if used >= 1 then raise exception 'ad_required'; end if; if not (exists(select 1 from public.bottles where author = auth.uid() and created_at >= today::timestamptz) or exists(select 1 from public.replies where author = auth.uid() and created_at >= today::timestamptz)) then raise exception 'engage'; end if; r := floor(random() * 100); reward := case when r < 50 then 2 when r < 78 then 4 when r < 92 then 6 when r < 98 then 10 else 20 end; update public.wallet set gems = gems + reward, xp = xp + 2, cards_day = today, cards_used = used + 1 where uid = auth.uid(); return json_build_object('reward', reward, 'gems', w.gems + reward); end $function$;
CREATE OR REPLACE FUNCTION public.journey_claim() RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare w public.wallet; n int; st public.journey_stations; today date := (now() at time zone 'utc')::date; ns int; bonus int; begin if auth.uid() is null then raise exception 'auth'; end if; insert into public.wallet(uid) values (auth.uid()) on conflict do nothing; select * into w from public.wallet where uid = auth.uid() for update; if w.last_claim = today then raise exception 'already'; end if; select count(*) into n from public.journey_stations; select * into st from public.journey_stations where idx = w.journey_pos % n; ns := case when w.last_claim = today - 1 then w.streak + 1 else 1 end; bonus := case when ns % 7 = 0 then 15 else 0 end; update public.wallet set gems = gems + st.gems + bonus, xp = xp + 10, journey_pos = journey_pos + 1, streak = ns, last_claim = today where uid = auth.uid(); return (public.journey_state()::jsonb || jsonb_build_object('reward', st.gems + bonus, 'bonus', bonus))::json; end $function$;
CREATE OR REPLACE FUNCTION public.riddle_answer(p_text text) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare w public.wallet; today date := (now() at time zone 'utc')::date; n int; r public.riddles; tries int; ok boolean; a text; g int; begin if auth.uid() is null then raise exception 'auth'; end if; insert into public.wallet(uid) values (auth.uid()) on conflict do nothing; select * into w from public.wallet where uid = auth.uid() for update; if w.riddle_day = today and w.riddle_done then raise exception 'done'; end if; tries := case when w.riddle_day = today then w.riddle_tries else 0 end; if tries >= 5 then raise exception 'no_tries'; end if; select count(*) into n from public.riddles; select * into r from public.riddles where idx = (today - date '2026-01-01') % n; ok := false; foreach a in array r.answers loop if public.nilo_norm(a) = public.nilo_norm(left(p_text, 60)) then ok := true; end if; end loop; g := w.gems; if ok then g := g + 6; end if; update public.wallet set riddle_day = today, riddle_tries = tries + 1, riddle_done = ok, gems = g, xp = xp + (case when ok then 3 else 0 end) where uid = auth.uid(); return json_build_object('correct', ok, 'gems', g, 'tries_left', greatest(0, 4 - tries)); end $function$;
-- Gems for real engagement: +2 gems for each of the first 3 papyri thrown per day.
create or replace function public.nilo_gem_on_throw() returns trigger language plpgsql security definer set search_path to 'public' as $f$ declare n int; begin select count(*) into n from public.bottles where author = new.author and created_at >= (now() at time zone 'utc')::date::timestamptz; if n <= 3 then insert into public.wallet(uid) values (new.author) on conflict do nothing; update public.wallet set gems = gems + 2 where uid = new.author; end if; return new; end $f$;
drop trigger if exists nilo_gem_throw on public.bottles;
create trigger nilo_gem_throw after insert on public.bottles for each row execute function public.nilo_gem_on_throw();
select 'ok' as done;
